const __result = (() => {
// --- Read Config ---
// Read the configuration from the MASTER CONFIG node
const CONFIG = $node["MASTER CONFIG"].json.loyverse_ids;

// --- Main Logic ---
const shiftsData = $items("Get Yesterday's Shifts From Loyverse");
const receiptsData = $items("Get Yesterday's Receipts From Loyverse");
const itemMasterData = $items("Format Product Data");
const historicalData = $items("Read Historical Data").map(item => item.json);
const shifts = (shiftsData.length > 0 && shiftsData[0].json) ? shiftsData[0].json.shifts || [] : [];
const receipts = (receiptsData.length > 0 && receiptsData[0].json) ? receiptsData[0].json.receipts || [] : [];
const allItems = itemMasterData.map(item => item.json);

if (shifts.length === 0 && receipts.length === 0) {
  return [{ json: { "message": "No shifts or receipts found to process." } }];
}

// Build a map of all items for fast lookup
const itemMap = {};
for (const item of allItems) {
  itemMap[item.variant_id] = item;
}

const businessDateString = $items("Calculate Shift Time")[0].json.businessDate;
const businessDate = new Date(businessDateString + 'T12:00:00Z');

// --- Initialize Metrics ---
const metrics = {
  date: businessDateString,
  weekday: businessDate.toLocaleString('en-US', { timeZone: 'UTC', weekday: 'short' }),
  gross_profit: 0,
  net_operating_profit: 0,
  best_seller_by_quantity_name: 'N/A',
  best_seller_by_quantity_count: 0,
  best_seller_by_profit_name: 'N/A',
  best_seller_by_profit_amount: 0,
  weekday_performance_vs_avg: 'N/A',
  weekday_rank: 'N/A',
  month_performance_vs_avg: 'N/A',
  ATV: 0,
  IPT: 0,
  total_discounts_amount: 0,
  total_discounts_count: 0,
  rolling_30_day_nop: 0,
  wtd_net_operating_profit: 0,
  profit_tendency: '➡️',
  // New generic totals
  total_cash_net: 0,
  total_qr_payments: 0,
  total_cash_difference: 0,
  totalGrossRevenue: 0 // Will be calculated from receipts
};

// Dynamically create category metrics
for (const categoryName of Object.values(CONFIG.CATEGORIES)) {
  const safeCategoryName = categoryName.replace(/ /g, '_').replace(/\./g, '');
  metrics[`${safeCategoryName}_items_sold`] = 0;
  metrics[`${safeCategoryName}_revenue`] = 0;
  metrics[`${safeCategoryName}_profit`] = 0;
}

// --- Process Shifts (Flexible) ---
let total_paid_out = 0;
const relevantShifts = shifts.filter(s => CONFIG.pos_device_ids.includes(s.pos_device_id));

for (const shift of relevantShifts) {
  metrics.total_cash_net += (shift.actual_cash - shift.starting_cash);
  metrics.total_discounts_amount += shift.discounts || 0;
  metrics.total_cash_difference += (shift.actual_cash - shift.expected_cash);
  total_paid_out += shift.paid_out || 0;

  // Find all QR payments for this shift
  for (const payment of shift.payments) {
    if (CONFIG.qr_payment_type_ids.includes(payment.payment_type_id)) {
      metrics.total_qr_payments += payment.money_amount;
    }
  }
}

// --- Process Receipts ---
const itemCounts = {};
const itemProfits = {};
let totalItemsSold = 0;

for (const receipt of receipts) {
  if (receipt.total_discounts > 0) {
    metrics.total_discounts_count++;
  }

  for (const lineItem of receipt.line_items) {
    totalItemsSold += lineItem.quantity;
    const masterItem = itemMap[lineItem.variant_id];
    if (!masterItem) continue;

    const cost = masterItem.cost || 0;
    const grossRevenue = lineItem.total_money || 0;
    metrics.totalGrossRevenue += grossRevenue; // Use this as the main revenue metric
    const revenueBeforeVat = (grossRevenue / 107) * 100;
    const profit = revenueBeforeVat - (cost * lineItem.quantity);

    metrics.gross_profit += profit;

    const itemName = masterItem.variant_name === 'Default' ? masterItem.item_name : `${masterItem.item_name} (${masterItem.variant_name})`;
    itemCounts[itemName] = (itemCounts[itemName] || 0) + lineItem.quantity;
    itemProfits[itemName] = (itemProfits[itemName] || 0) + profit;

    // Add to category totals
    const categoryName = CONFIG.CATEGORIES[masterItem.category_id];
    if (categoryName) {
      const safeCategoryName = categoryName.replace(/ /g, '_').replace(/\./g, '');
      metrics[`${safeCategoryName}_revenue`] += grossRevenue;
      metrics[`${safeCategoryName}_profit`] += profit;
    }
  }
}

// --- Final Calculations ---
metrics.net_operating_profit = metrics.gross_profit - total_paid_out;

if (receipts.length > 0) {
  metrics.ATV = metrics.totalGrossRevenue / receipts.length;
  metrics.IPT = totalItemsSold / receipts.length;
}

// Best Seller (Quantity)
let maxQuantity = 0;
for (const itemName in itemCounts) {
  if (itemCounts[itemName] > maxQuantity) {
    maxQuantity = itemCounts[itemName];
    metrics.best_seller_by_quantity_name = itemName;
    metrics.best_seller_by_quantity_count = maxQuantity;
  }
}

// Best Seller (Profit)
let maxProfit = -Infinity;
for (const itemName in itemProfits) {
  if (itemProfits[itemName] > maxProfit) {
    maxProfit = itemProfits[itemName];
    metrics.best_seller_by_profit_name = itemName;
    metrics.best_seller_by_profit_amount = maxProfit;
  }
}

// --- Historical Calculations ---
// Note: This uses totalGrossRevenue (from receipts) as the "Total Revenue"
const todayRevenue = metrics.totalGrossRevenue; 
const todayWeekday = metrics.weekday;
const todayMonth = businessDate.getMonth();
const todayYear = businessDate.getFullYear();
const oneYearAgo = new Date();
oneYearAgo.setFullYear(oneYearAgo.getFullYear() - 1);

// Weekday Performance
const sameWeekdayHistory = historicalData.filter(row => {
  const rowDate = new Date(row.Date);
  const rowWeekday = rowDate.toLocaleString('en-US', { timeZone: 'UTC', weekday: 'short' });
  return rowWeekday === todayWeekday && rowDate >= oneYearAgo;
});
if (sameWeekdayHistory.length > 0) {
  const totalRevenue = sameWeekdayHistory.reduce((sum, row) => sum + (parseFloat(row['Total Revenue']) || 0), 0);
  const avgRevenue = totalRevenue / sameWeekdayHistory.length;
  metrics.weekday_performance_vs_avg = (((todayRevenue / avgRevenue) - 1) * 100).toFixed(2) + '%';
  const allRevenues = sameWeekdayHistory.map(row => parseFloat(row['Total Revenue']) || 0);
  allRevenues.push(todayRevenue);
  allRevenues.sort((a, b) => b - a);
  const rank = allRevenues.indexOf(todayRevenue) + 1;
  metrics.weekday_rank = `${rank} of ${allRevenues.length}`;
}

// Month Performance
const sameMonthHistory = historicalData.filter(row => {
  const rowDate = new Date(row.Date);
  return rowDate.getMonth() === todayMonth && rowDate.getFullYear() === todayYear;
});
if (sameMonthHistory.length > 0) {
  const totalRevenue = sameMonthHistory.reduce((sum, row) => sum + (parseFloat(row['Total Revenue']) || 0), 0);
  const avgRevenue = totalRevenue / sameMonthHistory.length;
  metrics.month_performance_vs_avg = (((todayRevenue / avgRevenue) - 1) * 100).toFixed(2) + '%';
}

// --- Rolling 30-Day & WTD Calculations ---
function getStartOfWeek(date) {
  const d = new Date(date);
  const day = d.getDay();
  const diff = d.getDate() - day + (day === 0 ? -6 : 1); // adjust when day is sunday
  d.setHours(0, 0, 0, 0); // Normalize time
  return new Date(d.setDate(diff));
}

const today = businessDate; 
const startOfCurrentWeek = getStartOfWeek(today);

// Rolling 30-Day
const endDate = new Date(today);
const startDate = new Date(today);
startDate.setDate(startDate.getDate() - 29); // 30-day window
const rolling30DayData = historicalData.filter(row => {
  const rowDate = new Date(row.Date + 'T12:00:00Z');
  return rowDate >= startDate && rowDate < endDate;
});
const historical30DayProfit = rolling30DayData.reduce((sum, row) => {
  return sum + (parseFloat(row['Net Operating Profit']) || 0);
}, 0);
metrics.rolling_30_day_nop = historical30DayProfit + metrics.net_operating_profit;

// Week-to-Date
const sameWeekData = historicalData.filter(row => {
  const rowDate = new Date(row.Date + 'T12:00:00Z');
  return rowDate >= startOfCurrentWeek && rowDate < today;
});
const historicalWtdProfit = sameWeekData.reduce((sum, row) => {
  return sum + (parseFloat(row['Net Operating Profit']) || 0);
}, 0);
metrics.wtd_net_operating_profit = historicalWtdProfit + metrics.net_operating_profit;

// Profit Tendency
const fourWeeksAgo = new Date(startOfCurrentWeek);
fourWeeksAgo.setDate(fourWeeksAgo.getDate() - 28);
const last4WeeksData = historicalData.filter(row => {
  const rowDate = new Date(row.Date + 'T12:00:00Z');
  return rowDate >= fourWeeksAgo && rowDate < startOfCurrentWeek;
});
if (last4WeeksData.length > 0) {
  const last4WeeksTotalProfit = last4WeeksData.reduce((sum, row) => {
    return sum + (parseFloat(row['Net Operating Profit']) || 0);
  }, 0);
  const avgWeeklyProfit = last4WeeksTotalProfit / 4;
  if (metrics.wtd_net_operating_profit > avgWeeklyProfit) {
    metrics.profit_tendency = '⬆️';
  } else if (metrics.wtd_net_operating_profit < avgWeeklyProfit) {
    metrics.profit_tendency = '⬇️';
  }
}

return [{ json: metrics }];
})();
return { body: __unwrap(__result) };

