// --- CONFIGURATION ---
// Get config from the MASTER CONFIG node
const config = $node["MASTER CONFIG"].json.business_settings;

// Get the shift end time (e.g., "02:00") from the config
const shiftEndTime = config.shiftEnd; 

// Get the timezone (e.g., "Asia/Bangkok")
const TIMEZONE = config.timezone;


// 1. Calculate the new "Changeover" time
// Parse the "HH:mm" string into numbers
const [endHour, endMinute] = shiftEndTime.split(':').map(Number);

// Calculate the changeover time (2 hours after shift end)
// setHours() is smart and handles hour numbers > 23 automatically
const changeoverHour = endHour + 2; 
const changeoverMinute = endMinute;

// 2. Get the current time in your specified timezone
const nowInUserTz = new Date(new Date().toLocaleString('en-US', { timeZone: TIMEZONE }));

// 3. Determine the end of the report window
// First, set a potential end date to *today's* changeover time
let reportEndDate = new Date(nowInUserTz);
reportEndDate.setHours(changeoverHour, changeoverMinute, 0, 0);

// 4. Check if the current time is *before* today's changeover
// We must create a separate date object for this comparison
let changeoverToday = new Date(nowInUserTz);
changeoverToday.setHours(changeoverHour, changeoverMinute, 0, 0);

// If "now" is before the changeover, the business day hasn't ended.
// We must report on the *previous* day's window.
if (nowInUserTz < changeoverToday) {
  // Wind the report end date back to *yesterday's* changeover time
  reportEndDate.setDate(reportEndDate.getDate() - 1);
}

// 5. Calculate the start of the report window
// The API query window starts exactly 24 hours before the end time.
const reportStartDate = new Date(reportEndDate.getTime() - (24 * 60 * 60 * 1000));

// 6. Determine the "business date" (the calendar date the shift started)
const year = reportStartDate.getFullYear();
const month = String(reportStartDate.getMonth() + 1).padStart(2, '0');
const day = String(reportStartDate.getDate()).padStart(2, '0');
const businessDateString = `${year}-${month}-${day}`;

// 7. Return the dates as UTC ISO strings for the Loyverse API
return [{ 
  json: {
    start_of_day: reportStartDate.toISOString(), 
    end_of_day: reportEndDate.toISOString(),
    businessDate: businessDateString // Pass the correct date to the next nodes
  }
}];
})();
return { body: __unwrap(__result) };

